args_inline.content:
// slugkit: turn free text into a URL path segment.
// Used by the CMS to build article URLs from titles.

export function slugify(input: string): string {
  // Decompose accented letters into base letter + combining mark, then drop
  // the marks so "Café" folds to "cafe".
  const folded = input.normalize("NFD").replace(/\p{Diacritic}/gu, "");
  const lowered = folded.toLowerCase();
  const replaced = lowered.replace(/[^a-z0-9]+/g, "-");
  return replaced.replace(/^-+|-+$/g, "");
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { slugify } from "../src/slug.ts";

test("collapses runs of separators", () => {
  assert.equal(slugify("Hello  World!"), "hello-world");
});

test("trims hyphens from both edges", () => {
  assert.equal(slugify("--Hello  World!--"), "hello-world");
  assert.equal(slugify("!!!"), "");
});

test("folds accented letters to ASCII", () => {
  assert.equal(slugify("Café au lait"), "cafe-au-lait");
  assert.equal(slugify("Añejo Ünder Fjörd"), "anejo-under-fjord");
});

test("keeps digits and single hyphens intact", () => {
  assert.equal(slugify("Top 10 - Tips"), "top-10-tips");
});
